for (const [term, model] of Object.entries(modelNotes)) if (reviewedTerms[term]) reviewedTerms[term].review.model = model;

export function defineTerm(term: string): Term {
  const value = reviewedTerms[term];
  if (!value) throw new Error(`Missing reviewed mathematics definition: ${term}`);
  return value;
}
